import { createChange, definePrimitive, type ChangeDetails, type ChangeOptions } from "@ui-sdk/core"

import { settled } from "@/lib/action-refusal"

/**
 * Why the selection changed: `item-press` a row was opened, `focus-in` focus moved to another row while the detail
 * followed it, `close-press` Close or Back, `escape-key` Escape, `restore` the URL changed (Back, a deep link).
 */
type MasterDetailSelectReason = "item-press" | "focus-in" | "close-press" | "escape-key" | "restore" | "imperative"

type MasterDetailEntry = { id: string; label: string }

type MasterDetailOptions = {
  selectedId?: string | null
  defaultSelectedId?: string | null
  onSelectedIdChange?: (id: string | null, details: ChangeDetails<MasterDetailSelectReason>) => void
  /** The items `open` takes, for agents. Without them, `open` takes any id. */
  entries?: readonly MasterDetailEntry[]
}

function reasonOf(options: unknown): { reason: MasterDetailSelectReason; event?: Event } {
  if (typeof options !== "object" || options === null) return { reason: "imperative" }
  const { reason = "imperative", event } = options as ChangeOptions<MasterDetailSelectReason>
  return { reason, event: event instanceof Event ? event : undefined }
}

/** The selection of a list with a detail pane: `open(id)` shows an item's detail, `close()` goes back to the list. */
const masterDetail = definePrimitive({
  name: "master-detail",
  options: { selectedId: "value", defaultSelectedId: "value", onSelectedIdChange: "callback", entries: "value" },
  state: (options: MasterDetailOptions) => ({
    selectedId: options.selectedId !== undefined ? options.selectedId : (options.defaultSelectedId ?? null),
  }),
  sync: (options) => (options.selectedId === undefined ? {} : { selectedId: options.selectedId }),
  controlled: ["selectedId"],
  api: (context) => {
    const change = createChange(context)
    const entries = () => context.options().entries
    return {
      // Security: the agent bridge passes arguments unchecked.
      open(id: unknown, options?: ChangeOptions<MasterDetailSelectReason>) {
        const known = entries()
        if (typeof id !== "string" || (known !== undefined && !known.some((entry) => entry.id === id))) {
          const ids = known?.map((entry) => entry.id).join(", ")
          throw new RangeError(`No item "${String(id)}".${ids ? ` Items: ${ids}.` : ""}`)
        }
        if (context.store.get().selectedId === id) return true
        return settled(change("selectedId", id, reasonOf(options)), "open", reasonOf(options))
      },
      close(options?: ChangeOptions<MasterDetailSelectReason>) {
        if (context.store.get().selectedId === null) return true
        return settled(change("selectedId", null, reasonOf(options)), "close", reasonOf(options))
      },
      items: () => (entries() ?? []).map((entry) => ({ value: entry.id, label: entry.label })),
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "group",
      attrs: (state) => ({ "data-has-selection": state.selectedId === null ? undefined : "" }),
    }),
  }),
  agent: { actions: ["open", "close"], items: (api) => api.items() },
})

export { masterDetail }
export type { MasterDetailEntry, MasterDetailOptions, MasterDetailSelectReason }

"use client"

import { useEffectEvent, useLayoutEffect, useMemo, useRef, useState, useSyncExternalStore } from "react"

import type { UrlParamAdapter } from "@/lib/url-param"

const noSubscription = () => () => {}

/**
 * The selected id: `selectedId` when controlled, else the URL's when `url` is set, else its own state. `apply`
 * stores an accepted change wherever the value lives.
 */
function useSelectedId(
  selectedId: string | null | undefined,
  defaultSelectedId: string | null | undefined,
  url: UrlParamAdapter | undefined,
) {
  const [own, setOwn] = useState<string | null>(defaultSelectedId ?? null)
  const fromUrl = useSyncExternalStore(
    url?.subscribe ?? noSubscription,
    () => url?.read() ?? null,
    () => null,
  )
  let current = own
  if (selectedId !== undefined) current = selectedId
  else if (url) current = fromUrl
  const apply = (id: string | null) => {
    if (selectedId !== undefined) return
    if (url) url.write(id)
    else setOwn(id)
  }
  return [current, apply] as const
}

function rootFontSize() {
  return Number.parseFloat(getComputedStyle(document.documentElement).fontSize) || 16
}

/**
 * Whether `element` is narrower than `rem`, measured like the CSS container query that stacks the panes, so the two
 * agree. False on the server and until measured.
 */
function useNarrowerThan(element: HTMLElement | null, rem: number) {
  const [narrow, setNarrow] = useState(false)
  useLayoutEffect(() => {
    if (!element) return
    const measure = () => {
      const width = element.clientWidth
      setNarrow(width > 0 && width < rem * rootFontSize())
    }
    measure()
    if (typeof ResizeObserver === "undefined") return
    const observer = new ResizeObserver(measure)
    observer.observe(element)
    return () => observer.disconnect()
  }, [element, rem])
  return narrow
}

type FocusRequest = "detail" | "row"

type DetailFocusOptions = {
  selectedId: string | null
  /** Whether the panes are stacked, so the list is hidden while an item is open. */
  stacked: boolean
  list: HTMLElement | null
  detail: HTMLElement | null
  /** The focusable element of the row with this id; by default the row with `data-item-id` or `data-row-id`. */
  getRowElement?: (id: string) => HTMLElement | null | undefined
}

function focusHeading(pane: HTMLElement | null) {
  if (!pane) return
  const heading =
    pane.querySelector<HTMLElement>('[data-slot="master-detail-title"]') ??
    pane.querySelector<HTMLElement>("h1, h2, h3, h4, h5, h6")
  const target = heading ?? pane
  if (!target.hasAttribute("tabindex")) target.tabIndex = -1
  target.focus()
}

function defaultRow(list: HTMLElement | null, id: string) {
  const escaped = CSS.escape(id)
  const row = list?.querySelector<HTMLElement>(`[data-item-id="${escaped}"], [data-row-id="${escaped}"]`)
  if (!row) return null
  if (row.hasAttribute("tabindex")) return row
  return row.querySelector<HTMLElement>('[data-slot="list-item-primary"], a[href], button:not([disabled]), [tabindex]')
}

type DetailFocus = {
  /** Where focus goes after the next selection change: the open item's heading, or its row. */
  request: (target: FocusRequest) => void
  /** Focuses the open item's heading now, like when its row is pressed again. */
  heading: () => void
}

/**
 * Moves focus once the selection has rendered: to the detail's heading when it opens, back to the row that opened
 * it when it closes. A change that didn't ask (followed focus, an agent, the URL) only moves focus that would
 * otherwise be lost: on the body, in the pane being hidden, or in the detail that just closed.
 */
function useDetailFocus({ selectedId, stacked, list, detail, getRowElement }: DetailFocusOptions): DetailFocus {
  const previous = useRef(selectedId)
  const pending = useRef<FocusRequest | null>(null)
  const panes = useRef({ detail })
  const isStacked = useEffectEvent(() => stacked)
  const rowOf = useEffectEvent((id: string) => (getRowElement ? getRowElement(id) : defaultRow(list, id)))
  useLayoutEffect(() => {
    panes.current = { detail }
  }, [detail])
  useLayoutEffect(() => {
    const before = previous.current
    previous.current = selectedId
    const request = pending.current
    pending.current = null
    if (before === selectedId) return
    const active = document.activeElement
    const lost = active === null || active === document.body
    if (selectedId !== null) {
      const hidden = isStacked() && active !== null && list?.contains(active) === true
      if (request === "detail" || lost || hidden) focusHeading(detail)
      return
    }
    if (before === null) return
    const inDetail = active !== null && detail?.contains(active) === true
    if (request === "row" || lost || inDetail) rowOf(before)?.focus()
  }, [selectedId, list, detail])
  return useMemo<DetailFocus>(
    () => ({
      request: (target) => {
        pending.current = target
      },
      heading: () => focusHeading(panes.current.detail),
    }),
    [],
  )
}

const flagListeners = new Map<string, Set<() => void>>()

// Spec: storage can throw (blocked site data, a sandboxed frame).
function readFlag(key: string): boolean | undefined {
  let value: string | null = null
  try {
    value = localStorage.getItem(key)
  } catch {
    return undefined
  }
  return value === null ? undefined : value === "true"
}

function writeFlag(key: string, value: boolean) {
  try {
    localStorage.setItem(key, String(value))
  } catch {}
  for (const listener of flagListeners.get(key) ?? []) listener()
}

function subscribeFlag(key: string) {
  return (notify: () => void) => {
    const own = flagListeners.get(key) ?? new Set()
    flagListeners.set(key, own)
    own.add(notify)
    const onStorage = (event: StorageEvent) => {
      if (event.key === key) notify()
    }
    addEventListener("storage", onStorage)
    return () => {
      own.delete(notify)
      removeEventListener("storage", onStorage)
    }
  }
}

/** A boolean remembered in localStorage under `key`; the server and the first client render use `initial`. */
function useStoredFlag(key: string | undefined, initial: boolean) {
  const [own, setOwn] = useState(initial)
  const subscribe = useMemo(() => (key === undefined ? noSubscription : subscribeFlag(key)), [key])
  const stored = useSyncExternalStore(
    subscribe,
    () => (key === undefined ? undefined : readFlag(key)),
    () => undefined,
  )
  const value = key === undefined ? own : (stored ?? initial)
  const set = (next: boolean) => (key === undefined ? setOwn(next) : writeFlag(key, next))
  return [value, set] as const
}

/** Runs `sync(value)` after each commit where `value` changed, like telling a controller about a new state. */
function useSyncAfterCommit<T>(value: T, sync: (value: T) => void) {
  const run = useEffectEvent(sync)
  useLayoutEffect(() => {
    run(value)
  }, [value])
}

export { useDetailFocus, useNarrowerThan, useSelectedId, useStoredFlag, useSyncAfterCommit }
export type { FocusRequest }

"use client"

import { createContext, use, type ReactNode } from "react"
import {
  ArrowLeftIcon,
  PanelBottomCloseIcon,
  PanelBottomOpenIcon,
  PanelRightCloseIcon,
  PanelRightOpenIcon,
  XIcon,
} from "lucide-react"

import { Button } from "@/components/ui/button"
import { ScrollArea, ScrollAreaScrollbar, ScrollAreaThumb, ScrollAreaViewport } from "@/components/ui/scroll-area"

type MasterDetailLabels = {
  /** Names the list's region. */
  list: string
  /** Names the detail's region while nothing is open (an open item's title names it). */
  detail: string
  back: string
  close: string
  collapse: string
  expand: string
  resize: string
}

const masterDetailLabels: MasterDetailLabels = {
  list: "List",
  detail: "Detail",
  back: "Back",
  close: "Close detail",
  collapse: "Collapse detail",
  expand: "Expand detail",
  resize: "Resize detail",
}

/** What the detail pane shows for an item. */
type MasterDetailView = {
  title: ReactNode
  description?: ReactNode
  /** Buttons for the detail's header, after the title. */
  actions?: ReactNode
  content: ReactNode
}

type MasterDetailState = {
  selectedId: string | null
  /** Opens an item's detail, as a press on its row does. */
  open: (id: string) => void
  close: () => void
  /** Spread on a `ListItem`: its `id`, `selected` (`aria-current`) and an `onSelect` that opens it. */
  itemProps: (id: string) => { id: string; selected: boolean; onSelect: () => void }
}

const MasterDetailContext = createContext<MasterDetailState | null>(null)

/** The selection of the nearest MasterDetail, for rows rendered deeper than its `list` function. */
function useMasterDetail() {
  const context = use(MasterDetailContext)
  if (!context) throw new Error("useMasterDetail must be used inside a MasterDetail.")
  return context
}

const bar = "flex flex-wrap items-center gap-items border-b px-inset-item py-inline"

function MasterDetailListPane({
  label,
  header,
  toolbar,
  paneRef,
  onFocusRow,
  children,
}: {
  label: string
  header?: ReactNode
  toolbar?: ReactNode
  paneRef: (element: HTMLElement | null) => void
  onFocusRow: (target: EventTarget) => void
  children: ReactNode
}) {
  return (
    <section
      ref={paneRef}
      aria-label={label}
      data-slot="master-detail-list"
      className="flex size-full min-h-0 min-w-0 flex-col"
    >
      {header !== undefined && (
        <div data-slot="master-detail-header" className={bar}>
          {header}
        </div>
      )}
      {toolbar !== undefined && (
        <div data-slot="master-detail-toolbar" className={bar}>
          {toolbar}
        </div>
      )}
      <ScrollArea className="flex min-h-0 flex-1 flex-col">
        <ScrollAreaViewport
          className="h-auto min-h-0 flex-1 p-inline"
          onFocus={(event) => onFocusRow(event.target)}
          render={(part) => <div {...part} data-slot="master-detail-list-body" />}
        >
          {children}
        </ScrollAreaViewport>
        <ScrollAreaScrollbar data-agent-hidden="" />
      </ScrollArea>
    </section>
  )
}

type DetailHeaderProps = {
  view: MasterDetailView
  titleId: string
  headingLevel: 2 | 3 | 4
  labels: MasterDetailLabels
  /** Back on a stacked layout; Close and Collapse beside the list. */
  stacked: boolean
  onClose?: () => void
  onCollapse?: () => void
}

function MasterDetailDetailHeader({
  view,
  titleId,
  headingLevel,
  labels,
  stacked,
  onClose,
  onCollapse,
}: DetailHeaderProps) {
  const Heading = `h${headingLevel}` as const
  const close = stacked ? undefined : onClose
  const collapse = stacked ? undefined : onCollapse
  return (
    <header data-slot="master-detail-detail-header" className="flex flex-col gap-items border-b p-inset-surface">
      {stacked && onClose && (
        <div className="flex">
          <Button variant="ghost" size="sm" onClick={onClose} aria-keyshortcuts="Escape">
            <ArrowLeftIcon className="rtl:-scale-x-100" />
            {labels.back}
          </Button>
        </div>
      )}
      <div className="flex flex-wrap items-start gap-items">
        <div className="flex min-w-0 grow basis-48 flex-col gap-inline">
          <Heading
            id={titleId}
            tabIndex={-1}
            data-slot="master-detail-title"
            className="text-title-sm tracking-tight wrap-anywhere focus:outline-none"
          >
            {view.title}
          </Heading>
          {view.description !== undefined && <p className="text-body-sm text-muted-foreground">{view.description}</p>}
        </div>
        {(view.actions !== undefined || close || collapse) && (
          <div className="flex shrink-0 flex-wrap items-center gap-inline">
            {view.actions}
            {collapse && (
              <Button variant="ghost" size="icon" aria-label={labels.collapse} aria-expanded onClick={collapse}>
                <PanelRightCloseIcon className="rtl:-scale-x-100" />
              </Button>
            )}
            {close && (
              <Button variant="ghost" size="icon" aria-label={labels.close} onClick={close}>
                <XIcon />
              </Button>
            )}
          </div>
        )}
      </div>
    </header>
  )
}

function MasterDetailRail({ label, onExpand }: { label: string; onExpand: () => void }) {
  return (
    <div data-slot="master-detail-rail" className="flex flex-col items-center py-inline">
      <Button variant="ghost" size="icon" aria-label={label} aria-expanded={false} onClick={onExpand}>
        <PanelRightOpenIcon className="rtl:-scale-x-100" />
      </Button>
    </div>
  )
}

type IdleDetailProps = {
  title?: ReactNode
  titleId: string
  labels: MasterDetailLabels
  /** Stacked, it collapses to a bar; beside the list, to the rail. */
  stacked: boolean
  collapsed: boolean
  /** Shows the collapse button. */
  onToggle?: () => void
  children: ReactNode
}

/** The detail while nothing is open: `emptyDetail`, with a bar that collapses it when it stays on screen. */
function MasterDetailIdle({ title, titleId, labels, stacked, collapsed, onToggle, children }: IdleDetailProps) {
  const hasBar = title !== undefined || onToggle !== undefined
  const CollapseIcon = stacked ? PanelBottomCloseIcon : PanelRightCloseIcon
  return (
    <>
      {hasBar && (
        <div
          data-slot="master-detail-idle-bar"
          className="flex min-h-control items-center gap-items border-b px-inset-item py-inline in-data-collapsed:border-b-0"
        >
          {title !== undefined && (
            <div id={titleId} data-slot="master-detail-idle-title" className="min-w-0 flex-1 truncate text-title-sm">
              {title}
            </div>
          )}
          {onToggle && (
            <Button
              variant="ghost"
              size="icon"
              className="ms-auto"
              aria-label={collapsed ? labels.expand : labels.collapse}
              aria-expanded={!collapsed}
              onClick={onToggle}
            >
              {collapsed ? <PanelBottomOpenIcon /> : <CollapseIcon className="rtl:-scale-x-100" />}
            </Button>
          )}
        </div>
      )}
      {!collapsed && (
        // Spec: a scrolling viewport with nothing focusable inside becomes a tab stop, so it still scrolls by keyboard.
        <ScrollArea
          aria-labelledby={title === undefined ? undefined : titleId}
          aria-label={title === undefined ? labels.detail : undefined}
          className="flex min-h-0 flex-1 flex-col"
        >
          <ScrollAreaViewport>
            <div data-slot="master-detail-empty" className="flex min-h-full flex-col p-inset-surface">
              {children}
            </div>
          </ScrollAreaViewport>
          <ScrollAreaScrollbar>
            <ScrollAreaThumb />
          </ScrollAreaScrollbar>
        </ScrollArea>
      )}
    </>
  )
}

export {
  MasterDetailContext,
  MasterDetailDetailHeader,
  MasterDetailIdle,
  MasterDetailListPane,
  MasterDetailRail,
  masterDetailLabels,
  useMasterDetail,
}
export type { MasterDetailLabels, MasterDetailState, MasterDetailView }

"use client"

import type { ChangeDetails } from "@ui-sdk/core"
import { usePart, usePrimitive, type PartProps } from "@ui-sdk/react/primitive"
import { useId, useState, type CSSProperties, type ReactNode } from "react"

import {
  MasterDetailContext,
  MasterDetailDetailHeader,
  MasterDetailIdle,
  MasterDetailListPane,
  MasterDetailRail,
  masterDetailLabels,
  useMasterDetail,
  type MasterDetailLabels,
  type MasterDetailState,
  type MasterDetailView,
} from "@/components/ui/master-detail-parts"
import {
  masterDetail,
  type MasterDetailEntry,
  type MasterDetailSelectReason,
} from "@/components/ui/master-detail-primitive"
import {
  createResizableController,
  Resizable,
  ResizableHandle,
  ResizablePanel,
  type ResizableSize,
} from "@/components/ui/resizable"
import { ScrollArea, ScrollAreaScrollbar, ScrollAreaViewport } from "@/components/ui/scroll-area"
import { ShortcutScope } from "@/components/ui/shortcuts"
import {
  useDetailFocus,
  useNarrowerThan,
  useSelectedId,
  useStoredFlag,
  useSyncAfterCommit,
} from "@/components/ui/use-master-detail"
import { useShortcut } from "@/components/ui/use-shortcut"
import type { UrlParamAdapter } from "@/lib/url-param"
import { cn } from "@/lib/utils"

type MasterDetailProps = Omit<PartProps<"div">, "children" | "aria-label" | "style"> & {
  /** Names the block: agents open and close items through it by this name. */
  label: string
  /** The list, whose rows read the selection with `useMasterDetail()`. Or use `renderList`. */
  list?: ReactNode
  /** Renders the list with the selection: usually a `List` whose rows spread `state.itemProps(id)`. */
  renderList?: (state: MasterDetailState) => ReactNode
  /** The open item's view, or null when the id is unknown (then `emptyDetail` shows). */
  renderDetail: (id: string) => MasterDetailView | null
  /** Shown beside the list while nothing is open, on wide containers (and stacked ones with `idleDetail="visible"`). */
  emptyDetail?: ReactNode
  /** A title for `emptyDetail`, in a bar above it that also holds its collapse button; it names the pane. */
  emptyDetailTitle?: ReactNode
  /**
   * What a stacked container (under 42rem) shows while nothing is open: `hidden` (default) only the list; `visible`
   * keeps `emptyDetail` under the list, like a live monitor, with a button that collapses it to its bar. With
   * `collapsible`, the idle detail also gets that button beside the list, where it collapses to the rail.
   */
  idleDetail?: "hidden" | "visible"
  /**
   * `fill` (default) fills the parent's height, for a bounded box like an app shell's main column. `auto` sizes it to
   * its content between `--master-detail-min-height` (16rem) and `--master-detail-max-height` (40rem), the panes
   * scrolling inside, for a block in a scrolling page.
   */
  height?: "fill" | "auto"
  /** Above the list, like a title and a count. */
  header?: ReactNode
  /** Under the header, like a search field or filters. */
  toolbar?: ReactNode
  selectedId?: string | null
  defaultSelectedId?: string | null
  onSelectedIdChange?: (id: string | null, details: ChangeDetails<MasterDetailSelectReason>) => void
  /** The items agents may open, `{ id, label }`. Without them `open` takes any id and lists none. */
  items?: readonly MasterDetailEntry[]
  /** Keeps the selected id in the URL when uncontrolled: `createUrlParam("device")` from `@/lib/url-param`. */
  url?: UrlParamAdapter
  /** While an item is open on a wide container, moving focus to another row (j/k, arrows) opens it. */
  followFocus?: boolean
  /** Adds a button that collapses the detail to a rail with an expand button. */
  collapsible?: boolean
  defaultCollapsed?: boolean
  onCollapsedChange?: (collapsed: boolean) => void
  /** A handle between the panes resizes them, by drag or arrow keys. */
  resizable?: boolean
  /** The list's starting share of the width when resizable, like `40` (percent) or `"22rem"`. */
  defaultListSize?: ResizableSize
  /** Remembers the collapsed state and the panes' sizes in localStorage under keys that start with this. */
  storageKey?: string
  /** Shows a Close button in the detail's header on wide containers. Default true. */
  closable?: boolean
  /** The level of the open item's title. Default 2. */
  headingLevel?: 2 | 3 | 4
  /** The focusable element of a row, to return focus to. By default the row with `data-item-id` or `data-row-id`. */
  getRowElement?: (id: string) => HTMLElement | null | undefined
  /** The `ShortcutScope` that Escape belongs to. */
  scope?: string
  labels?: Partial<MasterDetailLabels>
  /**
   * `--master-detail-height` (100% by default) and `--master-detail-list-width` set the block's size; with
   * `height="auto"`, `--master-detail-min-height` and `--master-detail-max-height` bound it. `--master-detail-idle-height`
   * (50%) caps a stacked idle detail.
   */
  style?: CSSProperties
}

const stackBelowRem = 42
const railSize = "3.25rem"

const stackedClassNames = {
  list: "@max-2xl/master-detail:w-full @max-2xl/master-detail:!flex-auto @max-2xl/master-detail:border-e-0 @max-2xl/master-detail:data-covered:hidden",
  detail: "@max-2xl/master-detail:w-full @max-2xl/master-detail:!flex-auto @max-2xl/master-detail:data-idle:hidden",
  idleDetail:
    "@max-2xl/master-detail:w-full @max-2xl/master-detail:!flex-auto @max-2xl/master-detail:data-idle:!flex-none @max-2xl/master-detail:data-idle:max-h-(--master-detail-idle-height) @max-2xl/master-detail:data-idle:border-t @max-2xl/master-detail:data-idle:data-collapsed:max-h-none",
}

const heightClassNames = {
  fill: "h-(--master-detail-height)",
  auto: "h-auto min-h-(--master-detail-min-height) max-h-(--master-detail-max-height)",
}

function rootAttributes(label: string, narrow: boolean, height: "fill" | "auto", style: CSSProperties | undefined) {
  return {
    "aria-label": label,
    "data-slot": "master-detail",
    "data-stacked": narrow ? "" : undefined,
    "data-height": height,
    style: {
      "--master-detail-height": "100%",
      "--master-detail-min-height": "16rem",
      "--master-detail-max-height": "40rem",
      "--master-detail-idle-height": "50%",
      "--master-detail-list-width": "clamp(16rem, 38%, 26rem)",
      ...style,
    } as CSSProperties,
  }
}

function rowIdOf(target: EventTarget) {
  if (!(target instanceof Element) || target.closest("[data-slot=list-item-actions]")) return undefined
  const row = target.closest<HTMLElement>("[data-item-id], [data-row-id]")
  return row?.dataset.itemId ?? row?.dataset.rowId
}

/**
 * A list with a detail pane: side by side on wide containers, stacked below 42rem (the list, or the open item with
 * a Back button). Opening moves focus to the detail's heading; closing returns it to the row.
 */
function MasterDetail({
  label,
  list,
  renderList,
  renderDetail,
  emptyDetail,
  emptyDetailTitle,
  idleDetail = "hidden",
  height = "fill",
  header,
  toolbar,
  selectedId: selectedIdProp,
  defaultSelectedId,
  onSelectedIdChange,
  items,
  url,
  followFocus = false,
  collapsible = false,
  defaultCollapsed = false,
  onCollapsedChange,
  resizable = false,
  defaultListSize = 38,
  storageKey,
  closable = true,
  headingLevel = 2,
  getRowElement,
  scope = "master-detail",
  labels: overrides,
  className,
  style,
  ...props
}: MasterDetailProps) {
  const labels = { ...masterDetailLabels, ...overrides }
  const [root, setRoot] = useState<HTMLDivElement | null>(null)
  const [listPane, setListPane] = useState<HTMLElement | null>(null)
  const [detailPane, setDetailPane] = useState<HTMLElement | null>(null)
  const titleId = useId()
  const idleTitleId = useId()
  const generatedId = useId()
  const detailPanel = `${storageKey ?? generatedId}-detail`
  const [resize] = useState(createResizableController)

  const narrow = useNarrowerThan(root, stackBelowRem)
  const [selectedId, apply] = useSelectedId(selectedIdProp, defaultSelectedId, url)
  const [storedCollapsed, storeCollapsed] = useStoredFlag(
    storageKey === undefined ? undefined : `${storageKey}:collapsed`,
    defaultCollapsed,
  )
  const collapsed = collapsible && storedCollapsed && !narrow
  const idleVisible = idleDetail === "visible"
  const setCollapsed = (next: boolean) => {
    if (next === storedCollapsed) return
    storeCollapsed(next)
    onCollapsedChange?.(next)
  }
  const focus = useDetailFocus({ selectedId, stacked: narrow, list: listPane, detail: detailPane, getRowElement })

  const handle = usePrimitive(masterDetail, {
    selectedId,
    entries: items,
    onSelectedIdChange: (id, details) => {
      onSelectedIdChange?.(id, details)
      if (!details.canceled) apply(id)
    },
  })

  const open = (id: string, reason: MasterDetailSelectReason = "item-press") => {
    if (reason === "item-press") {
      if (collapsed) setCollapsed(false)
      if (id === selectedId) {
        focus.heading()
        return
      }
    }
    if (!handle.api.open(id, { reason })) return
    if (reason === "item-press" && (!followFocus || narrow)) focus.request("detail")
  }
  const close = (reason: MasterDetailSelectReason) => {
    if (handle.api.close({ reason })) focus.request("row")
  }

  useShortcut("escape", () => close("escape-key"), {
    scope,
    enabled: narrow && selectedId !== null,
    allowInInput: true,
    description: labels.back,
  })

  useSyncAfterCommit(resizable && collapsible ? storedCollapsed : undefined, (value) => {
    if (value === true) resize.collapse(detailPanel)
    else if (value === false) resize.expand(detailPanel)
  })

  const state: MasterDetailState = {
    selectedId,
    open: (id) => open(id),
    close: () => close("imperative"),
    itemProps: (id) => ({ id, selected: id === selectedId, onSelect: () => open(id) }),
  }

  const follow = (target: EventTarget) => {
    if (!followFocus || selectedId === null || narrow) return
    const id = rowIdOf(target)
    if (id === undefined || id === selectedId) return
    if (items !== undefined && !items.some((item) => item.id === id)) return
    open(id, "focus-in")
  }

  const view = selectedId === null ? null : renderDetail(selectedId)
  const listSection = (
    <MasterDetailListPane
      label={labels.list}
      header={header}
      toolbar={toolbar}
      paneRef={setListPane}
      onFocusRow={follow}
    >
      {renderList ? renderList(state) : list}
    </MasterDetailListPane>
  )

  const idleCollapsed = idleVisible && narrow && storedCollapsed && view === null
  const idleToggle = idleVisible && (narrow || collapsible)
  let detailContent: ReactNode = (
    <MasterDetailIdle
      title={emptyDetailTitle}
      titleId={idleTitleId}
      labels={labels}
      stacked={narrow}
      collapsed={idleCollapsed}
      onToggle={idleToggle ? () => setCollapsed(!storedCollapsed) : undefined}
    >
      {emptyDetail}
    </MasterDetailIdle>
  )
  if (collapsed) {
    detailContent = <MasterDetailRail label={labels.expand} onExpand={() => setCollapsed(false)} />
  } else if (view) {
    detailContent = (
      <>
        <MasterDetailDetailHeader
          view={view}
          titleId={titleId}
          headingLevel={headingLevel}
          labels={labels}
          stacked={narrow}
          onClose={narrow || closable ? () => close("close-press") : undefined}
          onCollapse={collapsible ? () => setCollapsed(true) : undefined}
        />
        <ScrollArea className="flex min-h-0 flex-1 flex-col">
          <ScrollAreaViewport
            className="flex h-auto min-h-0 flex-1 flex-col gap-group p-inset-surface"
            render={(part) => <div {...part} data-slot="master-detail-body" />}
          >
            {view.content}
          </ScrollAreaViewport>
          <ScrollAreaScrollbar data-agent-hidden="" />
        </ScrollArea>
      </>
    )
  }
  const named = view !== null && !collapsed
  let labelledBy: string | undefined
  if (named) labelledBy = titleId
  else if (view === null && !collapsed && emptyDetailTitle !== undefined) labelledBy = idleTitleId
  const detailSection = (
    <section
      ref={setDetailPane}
      aria-labelledby={labelledBy}
      aria-label={labelledBy === undefined ? labels.detail : undefined}
      data-slot="master-detail-detail"
      className="flex size-full min-h-0 min-w-0 flex-col"
    >
      {detailContent}
    </section>
  )

  const covered = selectedId === null ? undefined : ""
  const idle = view === null ? "" : undefined
  const flag = collapsed || idleCollapsed ? "" : undefined
  const detailStacking = idleVisible ? stackedClassNames.idleDetail : stackedClassNames.detail
  // Workaround: UI SDK's group lays its panes out in a row with an inline style, so the stacked column needs `!`.
  const stackColumn = idleVisible ? "@max-2xl/master-detail:!flex-col" : undefined
  const body = resizable ? (
    <Resizable
      controller={resize}
      className={stackColumn}
      autoSaveId={storageKey === undefined ? undefined : `${storageKey}:layout`}
      onLayoutChange={(_layout, details) => {
        if (details.reason !== "imperative" && collapsible) setCollapsed(resize.isCollapsed(detailPanel))
      }}
    >
      <ResizablePanel
        id={`${storageKey ?? generatedId}-list`}
        defaultSize={defaultListSize}
        minSize="16rem"
        data-covered={covered}
        className={cn("flex overflow-hidden", stackedClassNames.list)}
      >
        {listSection}
      </ResizablePanel>
      <ResizableHandle aria-label={labels.resize} className="@max-2xl/master-detail:hidden" />
      <ResizablePanel
        id={detailPanel}
        minSize="20rem"
        collapsible={collapsible}
        collapsedSize={railSize}
        data-idle={idle}
        data-collapsed={flag}
        className={cn("flex overflow-hidden", detailStacking)}
      >
        {detailSection}
      </ResizablePanel>
    </Resizable>
  ) : (
    <>
      <div
        data-covered={covered}
        className={cn(
          "flex min-h-0 min-w-0 border-e",
          collapsed ? "flex-1" : "w-(--master-detail-list-width) shrink-0",
          stackedClassNames.list,
        )}
      >
        {listSection}
      </div>
      <div
        data-idle={idle}
        data-collapsed={flag}
        className={cn(
          "flex min-h-0 min-w-0",
          collapsed ? "w-(--sidebar-rail-width) shrink-0" : "flex-1",
          detailStacking,
        )}
      >
        {detailSection}
      </div>
    </>
  )

  return usePart(
    handle,
    "root",
    {},
    {
      ...props,
      ...rootAttributes(label, narrow, height, style),
      ref: setRoot,
      className: cn(
        "@container/master-detail flex w-full min-w-0 overflow-hidden bg-background",
        height === "auto" ? heightClassNames.auto : cn(heightClassNames.fill, "min-h-0"),
        className,
      ),
      children: (
        <MasterDetailContext value={state}>
          <ShortcutScope name={scope} className={cn("flex min-h-0 min-w-0 flex-1", !resizable && stackColumn)}>
            {body}
          </ShortcutScope>
        </MasterDetailContext>
      ),
    },
    "div",
  )
}

export { MasterDetail, masterDetailLabels, useMasterDetail }
export type {
  MasterDetailEntry,
  MasterDetailLabels,
  MasterDetailProps,
  MasterDetailSelectReason,
  MasterDetailState,
  MasterDetailView,
}
